def _edge_list(W: np.ndarray, directed: bool = False):
    """Edge list of the weight graph.

    directed=False (default, and exactly what the released implementation does) enumerates
    each undirected pair once, i < j, so the fusion penalty is
        gamma * sum_{i<j} w_ij ||u_i - u_j||     (the usual convex-clustering form).
    """
    ei, ej = np.nonzero(W > 0)
    if directed:
        keep = ei != ej
    else:
        keep = ei < ej
    ei, ej = ei[keep], ej[keep]
    return ei, ej, W[ei, ej].astype(np.float64)

