def n_distinct(A: np.ndarray, tol: float = 1e-6) -> int:
    """Number of distinct rows of A (KCC centroids are exactly equal on fused groups)."""
    A = np.asarray(A, dtype=np.float64)
    keys = np.round(A / tol).astype(np.int64)
    return int(len(np.unique(keys, axis=0)))


def labels_at_k(A: np.ndarray, k: int, linkage: str = "ward", require_distinct: bool = True):
    """Cut the agglomerative dendrogram of the centroids at k clusters.

    Degeneracy guard: if the fusion produced fewer than `k` distinct centroids, asking for a
    k-way cut only splits exactly-coincident points, so the resulting labels (and any NMI
    computed from them) are meaningless.  In that case None is returned.
    """
    A = np.asarray(A, dtype=np.float64)
    if require_distinct and n_distinct(A) < int(k):
        return None
    return AgglomerativeClustering(n_clusters=int(k), linkage=linkage).fit_predict(A)
